#include "CadDocument.h"
#include "SketchGeometry.h"
#include "CircularPattern.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <BRepGProp.hxx>
#include <GProp_GProps.hxx>
#include <numbers>
#include <cmath>
#include <iostream>
namespace {void check(bool b,const QString& message){if(!b)throw std::runtime_error(message.toStdString());}
std::vector<QString> verify(const CadDocument& d,int count,double width,const QString& sourceId){check(d.bodies().size()==size_t(count),"total occurrences including seed");std::vector<QString> ids;for(int i=0;i<count;++i){const auto& b=d.bodies()[i];ids.push_back(b.bodyId);check(b.summary["valid"].toBool()&&b.summary["closed"].toBool(),"valid occurrence");check(std::abs(b.summary["volumeMm3"].toDouble()-width*2*10)<1e-5,"equal actual volume");GProp_GProps props;BRepGProp::VolumeProperties(b.shape,props);const auto c=props.CentreOfMass();double angle=2*std::numbers::pi*i/count;check(c.Distance(gp_Pnt((4+width/2)*std::cos(angle),(4+width/2)*std::sin(angle),5))<1e-5,"actual angular centroid");check(b.summary["circularPattern"].toObject()["index"]==i,"occurrence metadata");if(i==0)check(b.bodyId==sourceId,"seed retains original bodyID");else {check(!b.supportFaces.empty()&&!b.solidEdges.empty(),"copies retain actual mapped support and edges");for(const auto& f:b.supportFaces)check(f.bodyId==b.bodyId&&f.producerFeatureId==b.featureId&&f.provenance["transformedSourceFaceId"].isString(),"mapped face ownership/history");}}return ids;}}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument d;auto sketch=SketchGeometry::newFeature(d.activeOwnerId(),"XY","Radial spoke");sketch=SketchGeometry::addRectangle(sketch,{{"u1Mm",4},{"v1Mm",-1},{"u2Mm",16},{"v2Mm",1}});check(d.commit(SketchGeometry::replaceFeature(d.authored(),sketch),"Source").isEmpty(),"source sketch");check(d.commit(CadDocument::extrusionCandidate(d.authored(),{{"sketchId",sketch["id"]},{"profileId",d.sketches()[0].profiles[0].profileId},{"distanceMm",10}}),"Seed").isEmpty(),"source solid");const auto seed=d.bodies()[0];const auto source=d.authored();const auto evidence=qEnvironmentVariable("ALLOY_CIRCULAR_EVIDENCE");if(!evidence.isEmpty())check(d.save(evidence+"/source-seed.alloy").isEmpty(),"save native seed");auto args=QJsonObject{{"sourceBodyId",seed.bodyId},{"axis",QJsonObject{{"kind","originAxis"},{"axis","Z"}}},{"quantity",8}};check(d.commit(CadDocument::circularPatternCandidate(source,args),"Circular Bodies8").isEmpty(),"pattern commit");auto ids=verify(d,8,12,seed.bodyId);const auto feature=d.authored()["features"].toArray().last().toObject();check(d.bodies()[0].supportFaces[0].faceId==seed.supportFaces[0].faceId,"seed face remains original");const auto eight=d.authored();args["featureId"]=feature["id"];args["quantity"]=10;check(d.commit(CadDocument::circularPatternCandidate(d.authored(),args),"Count10").isEmpty(),"quantity edit");auto ten=verify(d,10,12,seed.bodyId);for(int i=0;i<8;++i)check(ten[i]==ids[i],"count edit preserves prefix occurrence UUIDs");const auto tenState=d.authored();d.history().undo();check(d.authored()==eight,"exact count undo");d.history().redo();check(d.authored()==tenState,"exact count redo");d.history().undo();
 auto edit=SketchGeometry::findFeature(d.authored(),sketch["id"].toString());auto p=edit["parameters"].toObject();auto points=p["points"].toArray();for(int i=0;i<points.size();++i){auto point=points[i].toObject();if(point["uMm"]==16)point["uMm"]=18;points[i]=point;}p["points"]=points;edit["parameters"]=p;check(d.commit(SketchGeometry::replaceFeature(d.authored(),edit),"Source width14").isEmpty(),"source edit rebuild");check(verify(d,8,14,seed.bodyId)==ids,"source edit retains all occurrence IDs");const auto edited=d.authored();d.history().undo();check(d.authored()==eight,"source exact undo");d.history().redo();check(d.authored()==edited,"source exact redo");
 auto hub=SketchGeometry::newFeature(d.activeOwnerId(),"XY","Hub");hub=SketchGeometry::addCircle(hub,{{"centerUMm",0},{"centerVMm",0},{"diameterMm",12}});check(d.commit(SketchGeometry::replaceFeature(d.authored(),hub),"Hub sketch").isEmpty(),"hub sketch");QJsonArray participants;for(const auto& id:ids)participants.append(id);const auto beforeJoin=d.authored();check(d.commit(CadDocument::extrusionCandidate(beforeJoin,{{"sketchId",hub["id"]},{"profileId",d.sketches().back().profiles[0].profileId},{"distanceMm",5},{"operation","join"},{"targetBodyIds",participants}}),"Eight participant Join").isEmpty(),"existing Extrude Join accepts generated body dependencies");check(d.bodies().size()==1&&d.bodies()[0].summary["valid"].toBool()&&d.bodies()[0].summary["topology"].toObject()["solids"]==1,"one connected actual eight-spoke/hub result");const auto joined=d.authored();d.history().undo();check(d.authored()==beforeJoin&&d.bodies().size()==8,"Join undo restores8 occurrences");d.history().redo();check(d.authored()==joined,"exact Join redo");QTemporaryDir temp;const auto path=temp.filePath("circular-bodies.alloy");check(d.save(path).isEmpty(),"save");CadDocument reopened;check(reopened.open(path).isEmpty()&&reopened.authored()==joined&&reopened.bodies().size()==1,"exact history/dependency reopen");
 auto invalid=args;invalid["quantity"]=4.5;bool refused=false;try{CadDocument::circularPatternCandidate(eight,invalid);}catch(const std::invalid_argument&){refused=true;}check(refused,"fractional total quantity refused");invalid=args;invalid["quantity"]=2;auto unavailable=CadDocument::circularPatternCandidate(joined,invalid);check(!d.commit(unavailable,"Remove Join participants").isEmpty()&&d.authored()==joined,"removed generated downstream references refuse atomically");std::cout<<"circular bodies8/count/source/transform lineage/8participantJoin/history/storage passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
